/**
 * Lessons as data. A lesson is a list of steps; a step says
 *
 *   say     the instruction, one sentence
 *   why     optional explanation shown under it
 *   target  what to point at, by the identifiers the interface already uses
 *   done    the condition that completes it (see conditions.js); `['read']` waits for "Continuar"
 *   tab     the side tab the target lives in, opened before pointing
 *   reveal  false when opening the target's own task is what the step teaches
 *   stage   optional, on the first step of a part of a long lesson: the card names the part
 *   spot    optional point of the scene to mark; a step that clicks the scene marks its point anyway
 *   act     how a test performs the step: 'click' (default), 'continue', ['fill', selector, text],
 *           ['select', selector, value], ['world', [x, y, z]] to click a point of the scene,
 *           ['key', name], ['click', selector], ['set', selector, value] to drag a slider and release it,
 *           or a list of these done in order
 *
 * `folder` names the folder of the tutorial list it is shown in (see LESSON_FOLDERS in tutor.js). `heavy` marks a lesson
 * on a large example scene, which the browser test gives more time.
 * A lesson with `continues` picks up the scene another lesson left. Nothing here is interface
 * code: adding a lesson is adding an entry. Every
 * lesson is run by tests/e2e/tutorials.test.js, which fails when a target
 * disappears or a condition can no longer be met.
 */
const ACCEPT = { say: 'Confirme a prévia no <b>botão destacado</b>, no topo da cena.', why: 'Tudo o que o assistente faz aparece primeiro como prévia, em verde. Nada entra na cena antes de você aceitar, e Ctrl+Z desfaz a proposta inteira.', target: '[data-action="accept-proposal"]' };
// Finding a model in Assets, picking it and putting it down on the marked point of the scene.
const search = (word, id) => ({ say: `Abra <b>Assets</b> e busque <b>${word}</b>.`, target: '[data-tab="assets"]', done: ['assetListed', id], act: [['click', '[data-tab="assets"]'], ['fill', '#asset-search', word]] });
const pick = (id, name, why) => ({ say: `Clique em <b>${name}</b>.`, ...(why ? { why } : {}), target: `[data-asset="${id}"]`, done: ['placingAsset', id] });
const drop = (id, say, point, why) => ({ say, ...(why ? { why } : {}), target: '#viewport', done: ['hasAsset', id], act: ['world', point] });
// Colours are typed as codes in the box beside the picker.
const fills = pairs => pairs.map(([field, value]) => ['fill', String(value).startsWith('#') ? `[data-hex="${field}"]` : `[data-field="${field}"]`, String(value)]);
const choose = (field, value) => `.choice-field:has([data-field="${field}"]) [data-choice="${value}"]`;
const AXES = { x: 'position-0', y: 'position-1', z: 'position-2' };
/**
 * The gestures of a real build. A person drags with the gizmo to the point marked in the scene and gets
 * close enough; the test types the numbers in Posição (only the axes that change, so that the step cannot
 * complete before the last one). Placement is not graded to the centimetre.
 */
const move = (which, say, point, axes, why) => ({ say, ...(why ? { why } : {}), target: '[data-action="tool-move"]', spot: point, done: ['near', which, point], act: [['click', '[data-action="tool-move"]'], ...fills([...axes].map(axis => [AXES[axis], point['xyz'.indexOf(axis)]]))] });
const turn = (which, say, degrees, why) => ({ say, ...(why ? { why } : {}), target: '[data-action="tool-rotate"]', done: ['facing', which, degrees], act: [['click', '[data-action="tool-rotate"]'], ['fill', '[data-field="object-yaw"]', String(degrees)]] });
const stretch = (which, say, factors, why) => ({ say, ...(why ? { why } : {}), target: '[data-action="tool-scale"]', done: ['scaledTo', which, factors], act: [['click', '[data-action="tool-scale"]'], ...fills(factors.flatMap((factor, axis) => factor === null ? [] : [[`scale-${axis}`, factor]]))] });
/** A colour chosen by eye in the picker (or typed in the box beside it); close enough counts. `which` is a model or kind, 'look', 'moon' or 'selected'. */
const tint = (which, path, field, hex, say, why) => ({ say, ...(why ? { why } : {}), target: `[data-field="${field}"]`, done: which === 'look' ? ['lookColorNear', path, hex] : which === 'moon' ? ['moonColorNear', hex] : which === 'selected' ? ['selectedColorNear', path, hex] : ['colorNear', which, path, hex], act: ['fill', `[data-hex="${field}"]`, hex] });
/** Duplicating (Ctrl+D) and dragging the copy with Mover (G) to the marked point. */
const copyTo = (id, number, say, point, why) => ({ say, ...(why ? { why } : {}), target: '[data-action="object-duplicate"]', spot: point, done: [['copies', id, number], ['selectedNear', point]], act: [['click', '[data-action="object-duplicate"]'], ['click', '[data-action="tool-move"]'], ...fills([['position-0', point[0]], ['position-1', point[1]], ['position-2', point[2]]])] });
const HOW = 'Neste tutorial você posiciona como numa construção de verdade: <b>G</b> move, <b>R</b> gira e <b>V</b> muda a escala, arrastando as alças do objeto até o ponto que pulsa na cena. Chegar perto basta. Quem quiser o número exato encontra em Propriedades → <b>Posição</b>.'
